// Stops early with a clear message if the Config node still has placeholder values.
const c = $input.first().json;
const problems = [];
if (!c.shop || c.shop === 'your-store' || /[.\/]/.test(c.shop)) problems.push('shop: enter only the part before .myshopify.com');
if (!/^https?:\/\/[^\/]+\.[a-z]{2,}/i.test(c.storeUrl || '')) problems.push('storeUrl: enter the public store address, starting with https://');
if (!/^\S+@\S+\.\S+$/.test(c.notifyEmail || '') || c.notifyEmail === 'you@example.com') problems.push('notifyEmail: enter the address that should get the review email');
if (!c.sheetId || /\s|\//.test(c.sheetId)) problems.push('sheetId: enter the Google Sheet ID (the long code in the sheet address, between /d/ and /edit)');
if (!c.sheetTab) problems.push('sheetTab: enter the name of the tab that holds the queue');
if (!c.blogHandle) problems.push('blogHandle: enter the handle of the Shopify blog to post to');
if (String(c.brandFacts || '').trim().length < 200) problems.push('brandFacts: this is the only thing the AI may say about the brand, so it cannot be empty');
if (problems.length) throw new Error('Finish the Config node first. ' + problems.join(' | '));
return $input.all();

// Turns the sheet into rows and picks the next topic: status "Queued", lowest priority number first,
// then top to bottom. Rows with any other status (Hold, Drafted, Published...) are skipped.
const res = $input.first().json ?? {};
if (res.error) throw new Error('Could not read the Google Sheet. Check the Google credential, Config.sheetId and Config.sheetTab. Google said: ' + JSON.stringify(res.error).slice(0, 400));
const values = res.values ?? [];
if (values.length < 2) throw new Error('The sheet tab is empty or has only a header row.');

const header = values[0].map(h => String(h ?? '').trim().toLowerCase());
const need = ['id', 'status', 'working_title', 'primary_keyword', 'brief'];
const missing = need.filter(n => !header.includes(n));
if (missing.length) throw new Error('The sheet is missing these column headings: ' + missing.join(', ') + '. Row 1 must keep the original headings.');

const colLetter = (index) => { let n = index + 1, s = ''; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };
const columns = {};
header.forEach((h, i) => { if (h) columns[h] = colLetter(i); });

const rows = values.slice(1)
  .map((r, i) => { const o = { rowNumber: i + 2 }; header.forEach((h, c) => { if (h) o[h] = String(r[c] ?? '').trim(); }); return o; })
  .filter(r => r.id || r.working_title);

const queued = rows.filter(r => r.status.toLowerCase() === 'queued' && r.working_title);
queued.sort((a, b) => (Number(a.priority) || 99) - (Number(b.priority) || 99) || a.rowNumber - b.rowNumber);

const counts = {};
for (const r of rows) { const s = r.status || '(blank)'; counts[s] = (counts[s] || 0) + 1; }

if (!queued.length) return [{ json: { found: false, counts, totalRows: rows.length } }];

const r = queued[0];
const list = (v) => String(v ?? '').split('|').map(s => s.trim()).filter(Boolean);
const yes = (v) => /^(yes|y|true|1)$/i.test(String(v ?? '').trim());

const topic = {
  id: r.id,
  rowNumber: r.rowNumber,
  working_title: r.working_title,
  primary_keyword: r.primary_keyword || r.working_title,
  research_query: r.research_query || r.primary_keyword || r.working_title,
  brief: r.brief,
  supporting_searches: list(r.supporting_searches),
  internal_links: list(r.internal_links).filter(u => /^https?:\/\//.test(u)),
  names_other_brands: yes(r.names_other_brands),
  health_sensitive: yes(r.health_sensitive),
};

return [{ json: { found: true, topic, columns, queuedLeft: queued.length - 1, nextUp: queued.slice(1, 4).map(q => q.working_title), counts } }];

// Nothing left to write: tell the owner instead of failing silently.
const cfg = $('Config').first().json;
const j = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const counts = Object.entries(j.counts ?? {}).map(([k, v]) => '<li>' + esc(k) + ': ' + v + '</li>').join('');
const html = [
  '<p>The weekly blog writer ran, but no row in the topic queue has the status <strong>Queued</strong>, so no post was written.</p>',
  '<p><a href="https://docs.google.com/spreadsheets/d/' + esc(cfg.sheetId) + '/edit">Open the queue</a> and add rows, or change a row from Hold to Queued.</p>',
  counts ? '<p>Rows by status:</p><ul>' + counts + '</ul>' : '',
].join('\n');
return [{ json: { to: cfg.notifyEmail, subject: 'Blog queue is empty: no post written this week', html } }];

// Pairs each generated image with its Shopify upload address and turns it into a file.

// Finds another node's items even when n8n has added a number to its name (for example "Collect Images1").
const itemsOf = (base) => {
  for (const name of [base, base + '1', base + '2', base + '3', base + '4', base + '5']) {
    try { const all = $(name).all(); if (all.length) return all; } catch (e) { /* not this one */ }
  }
  throw new Error('Could not find the output of "' + base + '". Check that the node exists and ran before this one.');
};
const plan = itemsOf('Collect Images')[0].json;
const gen = itemsOf('AI: Generate Image');
const res = $input.first().json ?? {};
const sc = res.data?.stagedUploadsCreate;
const errs = res.errors ?? (sc?.userErrors?.length ? sc.userErrors : null);
const targets = sc?.stagedTargets ?? [];
if (errs || targets.length !== plan.images.length || targets.some(x => !x?.url)) {
  throw new Error('Shopify would not accept the image uploads. Check that the Shopify app has the write_files scope and was reinstalled after you added it. Shopify said: ' + JSON.stringify(errs ?? res).slice(0, 500));
}
const out = [];
for (let i = 0; i < plan.images.length; i++) {
  const im = plan.images[i];
  const buf = Buffer.from(gen[im.index].json.data[0].b64_json, 'base64');
  const binary = await this.helpers.prepareBinaryData(buf, im.filename, im.mime);
  out.push({
    json: {
      slot: im.slot, alt: im.alt, filename: im.filename, bytes: buf.length,
      uploadUrl: targets[i].url,
      resourceUrl: targets[i].resourceUrl,
      headers: Object.fromEntries((targets[i].parameters ?? []).map(p => [p.name, p.value])),
    },
    binary: { data: binary },
  });
}
return out;

// Works out which uploads succeeded and tells Shopify to add those images to Content > Files.
const ups = $('Prepare Uploads').all().map(i => i.json);
const results = $input.all();
const registered = [];
const uploadErrors = [];
ups.forEach((u, i) => {
  const err = results[i]?.json?.error;
  if (err || !results[i]) uploadErrors.push({ slot: u.slot, reason: 'upload to Shopify failed (' + String(err?.description ?? err?.message ?? err ?? 'no response').slice(0, 200) + ')' });
  else registered.push({ slot: u.slot, alt: u.alt, resourceUrl: u.resourceUrl });
});
return [{ json: {
  count: registered.length,
  registered: registered.map(r => ({ slot: r.slot, alt: r.alt })),
  uploadErrors,
  graphql: {
    query: 'mutation Files($files: [FileCreateInput!]!) { fileCreate(files: $files) { files { id fileStatus alt } userErrors { field message code } } }',
    variables: { files: registered.map(r => ({ originalSource: r.resourceUrl, contentType: 'IMAGE', alt: r.alt })) },
  },
} }];

// Confirms Shopify registered the files and builds the "are they ready yet?" question.
const reg = $('Build File Records').first().json.registered;
const res = $input.first().json ?? {};
const fc = res.data?.fileCreate;
const files = fc?.files ?? [];
if (res.errors || fc?.userErrors?.length || files.length !== reg.length) {
  throw new Error('Shopify did not register the images. Shopify said: ' + JSON.stringify(res.errors ?? fc?.userErrors ?? res).slice(0, 500));
}
return [{ json: {
  slots: reg.map((r, i) => ({ slot: r.slot, alt: r.alt, fileId: files[i].id })),
  graphql: {
    query: 'query Ready($ids: [ID!]!) { nodes(ids: $ids) { ... on MediaImage { id fileStatus image { url width height } } } }',
    variables: { ids: files.map(f => f.id) },
  },
} }];

// Puts the images into the post and builds the Shopify "create hidden draft" call.
// Runs with or without images: if image generation failed, the post is still saved.

// Finds another node's output even when n8n has added a number to its name (for example "Parse Article1"),
// which happens when a node is pasted while an older copy is still on the canvas.
const itemsOf = (base) => {
  for (const name of [base, base + '1', base + '2', base + '3', base + '4', base + '5']) {
    try { const all = $(name).all(); if (all.length) return all; } catch (e) { /* not this one */ }
  }
  return [];
};
const maybe = (base) => itemsOf(base)[0]?.json ?? null;
const need = (base) => {
  const j = maybe(base);
  if (!j) throw new Error('Could not find the output of "' + base + '". Check that the node exists, ran before this one, and is named "' + base + '" (a number on the end is fine).');
  return j;
};
const inp = $input.first().json ?? {};
const cfg = need('Config');
const art = need('Parse Article');
const plan = need('Collect Images');
const blogId = (maybe('Check Shopify Setup') ?? maybe('Build Research Request'))?.blogId;
if (!blogId) throw new Error('Could not find which Shopify blog to post to. "Check Shopify Setup" should run near the start and output a blogId.');

// --- Which images made it all the way into Shopify Files
const placed = {};
const imageNotes = plan.failed.map(f => f.slot + ': not generated (' + f.reason + ')');
for (const e of maybe('Build File Records')?.uploadErrors ?? []) imageNotes.push(e.slot + ': ' + e.reason);
if (Array.isArray(inp.data?.nodes)) {
  const slots = need('Check Registered Files').slots;
  inp.data.nodes.forEach((n, i) => {
    const s = slots[i];
    if (!s) return;
    if (n?.fileStatus === 'READY' && n.image?.url) placed[s.slot] = { url: n.image.url, alt: s.alt, width: n.image.width, height: n.image.height };
    else if (n?.fileStatus === 'FAILED') imageNotes.push(s.slot + ': Shopify could not process the file');
    else imageNotes.push(s.slot + ': Shopify was still processing it after a minute. It should appear in Content > Files shortly; add it to the post by hand');
  });
}

// --- Swap the [[IMAGE_n]] markers for the images
const sized = (url) => url + (url.includes('?') ? '&' : '?') + 'width=1200';
const figure = (im) => '<figure style="margin:24px 0;"><img src="' + sized(im.url) + '" alt="' + String(im.alt).replace(/"/g, '&quot;') + '"' +
  (im.width && im.height ? ' width="' + im.width + '" height="' + im.height + '"' : '') +
  ' loading="lazy" style="width:100%;height:auto;display:block;border-radius:6px;"></figure>';

let body = art.body;
const insertBeforeNthH2 = (html, n, block) => {
  let seen = 0, done = false;
  const out = html.replace(/<h2\b/gi, (m) => { seen++; if (seen === n && !done) { done = true; return block + m; } return m; });
  return done ? out : html + block;
};
const h2Count = (body.match(/<h2\b/gi) || []).length;
[['inline_1', 1, 2], ['inline_2', 2, Math.max(3, Math.ceil(h2Count * 0.6))]].forEach(([slot, n, fallbackH2]) => {
  const marker = new RegExp('(<p>\\s*)?\\[\\[IMAGE_' + n + '\\]\\](\\s*</p>)?', 'i');
  const block = placed[slot] ? figure(placed[slot]) : '';
  if (marker.test(body)) body = body.replace(marker, block);
  else if (block) body = insertBeforeNthH2(body, fallbackH2, block);
});
body = body.replace(/(<p>\s*)?\[\[IMAGE_\d\]\](\s*<\/p>)?/gi, '');

const article = {
  blogId,
  title: art.title,
  author: { name: cfg.authorName },
  handle: art.handle,
  body,
  summary: art.summary,
  tags: art.tags,
  isPublished: false, // saved hidden; a person publishes it in Shopify
};
if (placed.featured) article.image = { url: placed.featured.url, altText: placed.featured.alt };

return [{ json: {
  graphql: {
    query: 'mutation CreateArticle($article: ArticleCreateInput!) { articleCreate(article: $article) { article { id title handle isPublished } userErrors { code field message } } }',
    variables: { article },
  },
  placed,
  imageNotes,
} }];

// The draft exists. Build two follow-up calls: SEO title/description on the post, and the
// queue row update in the Google Sheet (status, link, date).

// Finds another node's output even when n8n has added a number to its name (for example "Parse Article1"),
// which happens when a node is pasted while an older copy is still on the canvas.
const itemsOf = (base) => {
  for (const name of [base, base + '1', base + '2', base + '3', base + '4', base + '5']) {
    try { const all = $(name).all(); if (all.length) return all; } catch (e) { /* not this one */ }
  }
  return [];
};
const maybe = (base) => itemsOf(base)[0]?.json ?? null;
const need = (base) => {
  const j = maybe(base);
  if (!j) throw new Error('Could not find the output of "' + base + '". Check that the node exists, ran before this one, and is named "' + base + '" (a number on the end is fine).');
  return j;
};
const cfg = need('Config');
const pick = need('Pick Next Topic');
const art = need('Parse Article');
const created = $input.first().json.data.articleCreate.article;

const numericId = String(created.id).split('/').pop();
const adminUrl = 'https://admin.shopify.com/store/' + cfg.shop + '/content/articles/' + numericId;

const seo = {
  query: 'mutation Seo($metafields: [MetafieldsSetInput!]!) { metafieldsSet(metafields: $metafields) { metafields { key } userErrors { field message code } } }',
  variables: { metafields: [
    { ownerId: created.id, namespace: 'global', key: 'title_tag', type: 'single_line_text_field', value: art.seoTitle },
    { ownerId: created.id, namespace: 'global', key: 'description_tag', type: 'single_line_text_field', value: art.metaDescription },
  ] },
};

const tab = "'" + String(cfg.sheetTab).replace(/'/g, "''") + "'!";
const row = pick.topic.rowNumber;
const data = [];
const put = (col, value) => { if (pick.columns[col]) data.push({ range: tab + pick.columns[col] + row, values: [[value]] }); };
put('status', 'Drafted');
put('draft_link', adminUrl);
put('date_drafted', $now.toFormat('yyyy-MM-dd'));

return [{ json: { articleId: created.id, adminUrl, seo, sheet: { valueInputOption: 'USER_ENTERED', data } } }];

// Builds the review email: the blog draft, and what happened with the LinkedIn post if those steps are installed.
// It can sit straight after the sheet update or after the LinkedIn steps; it finds what it needs by node name.
// Swap the Gmail node after this for Slack, Telegram etc. if you prefer.

// Finds another node's output even when n8n has added a number to its name (for example "Parse Article1"),
// which happens when a node is pasted while an older copy is still on the canvas.
const itemsOf = (base) => {
  for (const name of [base, base + '1', base + '2', base + '3', base + '4', base + '5']) {
    try { const all = $(name).all(); if (all.length) return all; } catch (e) { /* not this one */ }
  }
  return [];
};
const maybe = (base) => itemsOf(base)[0]?.json ?? null;
const need = (base) => {
  const j = maybe(base);
  if (!j) throw new Error('Could not find the output of "' + base + '". Check that the node exists, ran before this one, and is named "' + base + '" (a number on the end is fine).');
  return j;
};
const cfg = need('Config');
const pick = need('Pick Next Topic');
const t = pick.topic;
const wr = maybe('Build Writing Request') ?? {};
const art = need('Parse Article');
const draft = need('Assemble Draft');
const prompts = itemsOf('Build Image Prompts').map(i => i.json);
const after = need('Build Follow-ups');
const seoRes = maybe('Shopify: Set SEO Title & Description') ?? {};
const sheetRes = maybe('Sheets: Mark Row Drafted') ?? $input.first().json ?? {};

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const list = (items, empty) => items.length ? '<ul>' + items.map(i => '<li>' + i + '</li>').join('') + '</ul>' : '<p>' + empty + '</p>';

const seoOk = !seoRes.error && !seoRes.errors && !(seoRes.data?.metafieldsSet?.userErrors ?? []).length && !!seoRes.data?.metafieldsSet;
const sheetOk = !sheetRes.error && Number(sheetRes.totalUpdatedCells ?? 0) > 0;

const slotName = { featured: 'Featured image', inline_1: 'In-body image 1', inline_2: 'In-body image 2' };
const imagesHtml = prompts.map(p => {
  const im = draft.placed[p.slot];
  return '<tr><td style="vertical-align:top;padding:6px;width:210px;">' +
    (im ? '<img src="' + esc(im.url) + (im.url.includes('?') ? '&amp;' : '?') + 'width=400" width="200" alt="" style="display:block;border-radius:4px;">' : '<em>not in the post</em>') +
    '</td><td style="vertical-align:top;padding:6px;"><strong>' + slotName[p.slot] + '</strong><br>Alt text: ' + esc(p.alt) + '<br><small>Scene asked for: ' + esc(p.scene) + '</small></td></tr>';
}).join('');

// --- LinkedIn: what was posted, or why nothing was. Left out entirely if the LinkedIn steps are not in the workflow.
const li = maybe('Build LinkedIn Post') ?? maybe('Build LinkedIn Email');
const liRes = maybe('LinkedIn: Publish Post') ?? maybe('LinkedIn') ?? maybe('Create a post');
const liErr = liRes?.error ? String(liRes.error.message ?? liRes.error.description ?? (typeof liRes.error === 'string' ? liRes.error : JSON.stringify(liRes.error))).slice(0, 400) : '';
const postBox = (text) => text ? '<div style="border:1px solid #d9cfbd;border-radius:6px;padding:12px 16px;margin:8px 0;white-space:pre-wrap;">' + esc(text) + '</div>' : '';
let linkedinState = 'none';
let linkedinHtml = '';
if (li && typeof li.post === 'boolean') {
  const shown = (li.notes ?? []).filter(n => !(li.post && /^The blog post was not live yet/.test(n)));
  const liNotes = shown.length ? list(shown.map(esc), '') : '';
  if (!li.post) {
    linkedinState = 'skipped';
    linkedinHtml = '<p style="color:#b00020"><strong>Nothing was posted to LinkedIn.</strong> ' + esc(li.reason) + '</p>' + liNotes +
      (li.text ? '<p>The text it prepared, if you want to fix it and post it by hand:</p>' + postBox(li.text) : '');
  } else if (liRes && !liErr && liRes.urn) {
    linkedinState = 'posted';
    linkedinHtml = '<p><strong>Posted to LinkedIn</strong> (' + li.characters + ' characters, ' + (li.mediaCategory === 'IMAGE' ? 'with the featured image' : 'text only') + '). ' +
      '<a href="https://www.linkedin.com/feed/update/' + esc(liRes.urn) + '/">Open the post</a></p>' +
      (li.blogLive ? '' : '<p style="color:#b00020"><strong>Publish the blog post soon.</strong> It was still hidden, so the LinkedIn post links to the blog front page, where readers will look for it.</p>') +
      liNotes + postBox(li.text);
  } else {
    linkedinState = 'failed';
    linkedinHtml = '<p style="color:#b00020"><strong>The LinkedIn post was prepared but not published.</strong> ' +
      (liErr ? 'LinkedIn said: ' + esc(liErr) : liRes ? 'LinkedIn did not confirm the post. Check your profile.' : 'The LinkedIn node did not run. Check that "Post to LinkedIn?" connects to it and that it connects to this node.') + '</p>' +
      '<p>The text, to post by hand:</p>' + postBox(li.text);
  }
}

const html = [
  '<p>A new blog draft is saved in Shopify as <strong>hidden</strong>. Nothing is live until you publish it.</p>',
  '<p><a href="' + esc(after.adminUrl) + '"><strong>Open the draft in Shopify</strong></a><br>',
  '<small>If the link does not open, go to Shopify admin &rarr; Content &rarr; Blog posts.</small></p>',
  '<table cellpadding="6" style="border-collapse:collapse">',
  '<tr><td><strong>Title</strong></td><td>' + esc(art.title) + '</td></tr>',
  '<tr><td><strong>Queue row</strong></td><td>' + esc(t.id) + ' (row ' + t.rowNumber + '), keyword: ' + esc(t.primary_keyword) + '</td></tr>',
  '<tr><td><strong>Length</strong></td><td>' + art.words + ' words</td></tr>',
  '<tr><td><strong>Tags</strong></td><td>' + esc(art.tags.join(', ')) + '</td></tr>',
  '<tr><td><strong>Left in queue</strong></td><td>' + pick.queuedLeft + (pick.nextUp.length ? '. Next: ' + esc(pick.nextUp[0]) : '') + '</td></tr>',
  '</table>',
  sheetOk ? '' : '<p style="color:#b00020"><strong>The Google Sheet was not updated.</strong> Set row ' + t.rowNumber + ' to "Drafted" by hand, or the same topic will be written again next week.</p>',

  linkedinHtml ? '<h3>LinkedIn</h3>' : '',
  linkedinHtml,

  '<h3>Automatic checks</h3>',
  list(art.checks.map(esc), 'Nothing flagged. Still read it through.'),

  '<h3>Figures and claims to check before publishing</h3>',
  art.claimsToVerify.length
    ? '<ol>' + art.claimsToVerify.map(c => '<li>' + esc(c.claim) + (c.source_url ? ' <a href="' + esc(c.source_url) + '">source</a>' : ' (no source given)') + '</li>').join('') + '</ol>'
    : '<p>The writer listed no figures. Still read it through.</p>',

  art.editorNotes ? '<h3>Notes from the writer</h3><p>' + esc(art.editorNotes) + '</p>' : '',

  '<h3>Images</h3>',
  '<p>These are AI-generated. Look for anything odd (hands, text, a logo) and swap in a real photo where you have one.</p>',
  '<table style="border-collapse:collapse">' + imagesHtml + '</table>',
  draft.imageNotes.length ? list(draft.imageNotes.map(esc), '') : '',

  '<h3>Search listing</h3>',
  seoOk ? '<p>Set on the post automatically:</p>' : '<p style="color:#b00020">Could not be set automatically. Paste these into "Search engine listing" on the post:</p>',
  '<p><strong>Page title:</strong> ' + esc(art.seoTitle) + '<br><strong>Meta description:</strong> ' + esc(art.metaDescription) + '</p>',

  '<h3>Pages the research read</h3>',
  list((wr.researchSources ?? []).slice(0, 25).map(s => '<a href="' + esc(s.url) + '">' + esc(s.title) + '</a>'), 'None recorded.'),
].filter(Boolean).join('\n');

return [{ json: { to: cfg.notifyEmail, subject: 'Blog draft ready: ' + art.title, html, adminUrl: after.adminUrl, sheetOk, seoOk, linkedin: linkedinState } }];

// Runs before any AI spend. Confirms the Shopify app has the permissions this workflow needs,
// finds the blog to post to, and lists the posts already on the site (the writer links to them
// and avoids repeating them).
const cfg = $('Config').first().json;



const shop = $input.first().json ?? {};
if (shop.errors) throw new Error('Shopify GraphQL error: ' + JSON.stringify(shop.errors).slice(0, 500));
const blogs = shop.data?.blogs?.nodes ?? [];
const blog = blogs.find(b => b.handle === cfg.blogHandle);
if (!blog) throw new Error('Blog handle "' + cfg.blogHandle + '" not found in Shopify. Available: ' + (blogs.map(b => b.handle).join(', ') || 'none'));

const base = String(cfg.storeUrl).replace(/\/+$/, '');
const existingArticles = (shop.data?.articles?.nodes ?? []).map(a => ({
  title: a.title, handle: a.handle, isPublished: a.isPublished,
  url: a.blog?.handle ? base + '/blogs/' + a.blog.handle + '/' + a.handle : null,
}));

return [{ json: { blogId: blog.id, blogHandle: blog.handle, existingArticles } }];

// Builds the writing request: brand facts + selling points + voice + structure + accuracy rules + image brief.
// Edit the wording here to change how every post is written. Brand facts live in the Config node.
const cfg = $('Config').first().json;

// The only tags a post may carry. Edit this list to change the tag filters on the blog.
// The writer picks one to three; Parse Article drops anything that is not on the list.
const ALLOWED_TAGS = ['Caffeine', 'Coffee & Health', 'Kenyan Coffee', 'Roast Guides', 'Flavor & Tasting', 'Brewing Guides', 'Coffee Brands', 'Coffee Basics', 'Decaf & Half-Caff'];

// How much the model "thinks" before writing. Thinking is billed as output and shares the maxTokens limit with the post,
// so too much of it leaves no room for the article. Options: 'minimal', 'low', 'medium', 'high'.
const WRITER_REASONING = 'low';

const pick = $('Pick Next Topic').first().json;
const t = pick.topic;
const shopify = $('Check Shopify Setup').first().json;
const res = $input.first().json ?? {};

// --- Research. The reply carries its sources in one of two ways, so read both:
//   1. links typed into the notes (one per fact), or
//   2. a separate citation list with the page, link and the passage used.
const msg = res.choices?.[0]?.message;
const notes = typeof msg?.content === 'string' ? msg.content.trim() : '';
const sources = new Map(); // link -> page title or site name
for (const raw of notes.match(/https?:\/\/[^\s|)\]>"']+/g) ?? []) {
  const url = raw.replace(/[.,;:]+$/, '');
  sources.set(url, url.replace(/^https?:\/\/(www\.)?/, '').split('/')[0]);
}
const citations = [];
const seen = new Set();
for (const an of msg?.annotations ?? []) {
  const c = an?.url_citation;
  if (!c?.url) continue;
  sources.set(c.url, c.title || c.url);
  const passage = String(c.content ?? '').replace(/[\s*#|]+/g, ' ').trim().slice(0, 240);
  if (seen.has(c.url + passage)) continue;
  seen.add(c.url + passage);
  citations.push('- ' + (c.title || c.url) + ' | ' + c.url + ' | "' + passage + '"');
}
if (notes.length < 300 || sources.size === 0) {
  const why = res.error?.description ?? res.error?.message ?? res.choices?.[0]?.error?.message
    ?? (notes.length < 300 ? 'it returned almost no notes' : 'it returned no source links at all, so it probably did not search the web');
  throw new Error('No post was written for "' + t.working_title + '" because the research was not usable: ' + why + '. The row is still Queued. Check the output of "AI: Research the Topic".');
}
const researchProblem = res.choices[0].finish_reason === 'length' ? 'The web research was cut off before it finished, so the notes may be incomplete.' : '';

// --- Pages the post may link to on our own site
const base = String(cfg.storeUrl).replace(/\/+$/, '');
const links = new Map();
for (const u of t.internal_links) links.set(u.replace(/\/+$/, ''), 'Suggested for this topic');
for (const line of String(cfg.linkTargets || '').split('\n')) {
  const [u, label] = line.split('|').map(s => s.trim());
  if (/^https?:\/\//.test(u || '') && !links.has(u.replace(/\/+$/, ''))) links.set(u.replace(/\/+$/, ''), label || 'Store page');
}
for (const a of shopify.existingArticles) {
  if (a.isPublished && a.url && !links.has(a.url)) links.set(a.url, 'Blog post: ' + a.title);
}
const allowedInternal = [...links.entries()].map(([url, label]) => ({ url, label }));

const monthYear = $now.toFormat('MMMM yyyy');
const words = Number(cfg.wordCount) || 1500;

const brandsRule = t.names_other_brands
  ? 'Other brands: name a brand only with a figure from RESEARCH, linked, stated neutrally, with "as listed when we checked in ' + monthYear + '". If the only source is a secondary database, name it and its caveat once above the table and say so in editor_notes. Do not rank brands by quality or tell readers to avoid one. Leave out any brand without a sourced figure. Never put Kirenge Gold in a ranking of high-caffeine brands.'
  : 'Other brands: do not name any other coffee brand, coffee chain or retailer.';

const healthBlock = t.health_sensitive ? [
  '',
  '=== HEALTH-SENSITIVE TOPIC ===',
  '- Attribute and link every health statement to a named source in RESEARCH, and give the size and length of any study.',
  '- Include one sentence telling readers who are pregnant, have a medical condition or take medication to ask their doctor.',
  '- No promises and no "best coffee for weight loss" picks. Do not offer our coffee as a way to get a health effect; the call to action is about taste and freshness.',
] : [];

const system = [
  'You write the Kirenge Gold coffee blog for home coffee drinkers in the United States who typed a question into Google. Give the clearest, most accurate answer to that question in our voice, and make clear why our coffee is worth buying.',
  '',
  '=== BRAND FACTS: say nothing about Kirenge Gold beyond these ===',
  String(cfg.brandFacts).trim(),
  '',
  '=== SELLING POINTS: every post states the first four at least once, in the section about our coffee and in the call to action ===',
  '- 100% Arabica beans.',
  '- Single origin: one family farm, Kirenge Farm in Kiambu County, Kenya, growing coffee since the 1950s. Never mention cooperatives, partner farms or other regions as sources.',
  '- Low acid: a smooth cup. For the light and medium roasts say "bright, fruity flavor", not "acidity" (this overrides the tasting notes above).',
  '- Fresh: roasted in small batches every week in Atlanta and shipped within 48 hours.',
  '- Use where they fit: hand-picked; grown at 1,500 to 1,800 meters on red volcanic soil; SL-28 and SL-34 varieties; light, medium and dark roast as whole bean, ground or pods; free shipping on subscriptions and on orders over $55.',
  '- Call the coffee "100% Kenyan Arabica". Never call it "AA", and leave Kenya\'s AA grade out unless the topic itself is about coffee grades.',
  '',
  '=== VOICE ===',
  '- A coffee-farming family talking to a friend: warm, plain, confident. "We" and "our" for the farm and company, "you" for the reader, never "I".',
  '- Plain American English, short sentences, paragraphs of one to three sentences. Explain a coffee term the first time you use it.',
  '- Be specific ("grind coarser", "195 to 205°F"). US units first, metric in parentheses.',
  '- No hype words (elevate, indulge, unleash, unlock, journey, game-changer, delve), no exclamation marks, no emoji, no question as the opening line.',
  '',
  '=== STRUCTURE ===',
  '1. Open with <p><strong>Short answer:</strong> ...</p>: 40 to 60 words that fully answer the primary search phrase.',
  '2. If the answer involves numbers or a comparison, follow with one small table and a line naming its source.',
  '3. Then h2 sections worded the way people search (use the supporting searches). Answer each heading in its first sentence.',
  '4. Use a table to compare three or more things (header row, at most four columns), an ol for steps, a ul for short lists.',
  '5. One short section (under 120 words) on how our coffee fits the topic, using the selling points.',
  '6. Near the end, an h2 call to action: two sentences and one link to the most relevant product, collection or subscription page.',
  '7. Then <h2>Frequently asked questions</h2> with 3 to 6 h3 questions the sections did not already answer, each answered in one to three sentences.',
  '8. End with <h2>Sources</h2>: a ul of links to the sources used.',
  '9. Put [[IMAGE_1]] in its own paragraph after the first or second h2 section and [[IMAGE_2]] about two-thirds of the way down. Never inside a table, a list or the FAQ.',
  '10. About ' + words + ' words of body text, not counting tables, the FAQ and Sources. Do not pad.',
  '',
  '=== ACCURACY ===',
  '1. Numbers: use a statistic, milligram figure, percentage, date, ranking or price only if it is in RESEARCH. Link it to its source the first time it appears in a section, using the URL given with that fact in RESEARCH (or, if it has none, the URL of the CITATIONS passage that supports it), and list it in claims_to_verify. If a figure has no URL, leave it out and say so in editor_notes. Brewing guidance (temperature, ratio, grind, time) needs no source. Simple arithmetic on RESEARCH figures is fine; mark it "calculated" in claims_to_verify.',
  '2. Our caffeine: say it is "in the normal range for 100% arabica coffee". Give no milligram figure for our coffee.',
  '3. Health: never say coffee treats, cures, prevents, burns fat, boosts metabolism, detoxes or helps anyone lose weight, and never say our coffee is gentle on the stomach or good for acid reflux. You may report what a named health authority or study in RESEARCH found, linked, with its limits.',
  '4. ' + brandsRule,
  '5. Links: to our own site use only URLs from ALLOWED INTERNAL LINKS, copied exactly, three to eight different pages in total. External links only to URLs that appear in RESEARCH or CITATIONS.',
  '6. Do not copy sentences from RESEARCH. Do not repeat an existing post: give the short version and link to it.',
  '7. Inside the post, never mention these instructions, the research notes or AI. Put gaps, doubts and brands left out in editor_notes.',
  ...healthBlock,
  '',
  '=== IMAGES ===',
  'Plan three photographs: "featured" (top of the post), "inline_1" (replaces [[IMAGE_1]]) and "inline_2" (replaces [[IMAGE_2]]). For each give:',
  '- scene: 35 to 70 words describing one photograph a food photographer could take: subject, surface, two or three props, camera angle and the moment. It must show what that part of the post is about. The three differ in subject, angle and distance; the featured one is the simplest.',
  '- alt: under 120 characters describing what is visible.',
  'Show only: brewed coffee in plain cups or glass, brewing gear in use, roasted, ground or green beans, ripe coffee cherries on a branch in close-up, measuring tools, a kitchen counter or table. A hand only if the action needs it, cropped at the wrist.',
  'Never: faces; farms, landscapes, buildings or people (nothing may pass as Kirenge Farm or our family); our bags or pods; other brands; text, numbers, labels or charts; medical or weight-loss imagery. Do not describe lighting or camera settings.',
  '',
  '=== FORMAT ===',
  'body_html uses only these tags: h2, h3, p, ul, ol, li, strong, em, a, blockquote, table, thead, tbody, tr, th, td. No h1, img, inline styles, classes or markdown.',
  'tags: choose one to three from this list, copied exactly, and no others: ' + ALLOWED_TAGS.join(' | ') + '.',
  'Deliver the post only by calling the submit_article tool, once. Do not reply in plain text.',
].join('\n');

const user = [
  'Today is ' + $now.toFormat('d MMMM yyyy') + '.',
  '',
  'TOPIC',
  'Working title: ' + t.working_title,
  'Primary search phrase: ' + t.primary_keyword,
  'Brief from the content plan: ' + t.brief,
  'Searches this post must answer (real Google searches that reached the site): ' + (t.supporting_searches.join(' | ') || '(none listed)'),
  '',
  'RESEARCH',
  notes,
  ...(citations.length ? [
    '',
    'CITATIONS: pages the research read, with the passage it took from each. Where a fact above has no link of its own, find the passage that supports it and use that URL.',
    citations.join('\n'),
  ] : []),
  '',
  'ALLOWED INTERNAL LINKS',
  allowedInternal.map(l => '- ' + l.url + ' | ' + l.label).join('\n'),
  '',
  'POSTS ALREADY ON THE BLOG (do not repeat them)',
  JSON.stringify(shopify.existingArticles.map(a => a.title)),
  '',
  'Write the post, then call the submit_article tool once with the finished post.',
].join('\n');

const imageItem = {
  type: 'object',
  properties: {
    scene: { type: 'string', description: 'One photographable scene, 35 to 70 words.' },
    alt: { type: 'string', description: 'Alt text under 120 characters.' },
  },
  required: ['scene', 'alt'],
};

const request = {
  model: cfg.writerModel,
  max_tokens: Number(cfg.maxTokens) || 16000,
  reasoning: { effort: WRITER_REASONING, exclude: true }, 
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  tools: [{ type: 'function', function: {
    name: 'submit_article',
    description: 'Submit the finished blog post and its three image briefs.',
    parameters: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Headline shown on the page. Under 65 characters. Contains the primary search phrase naturally.' },
        seo_title: { type: 'string', description: 'Title for Google results. Under 60 characters. Primary search phrase near the start.' },
        meta_description: { type: 'string', description: '140 to 155 characters. States the answer and gives a reason to click.' },
        handle: { type: 'string', description: 'URL slug: lowercase, hyphenated, 3 to 6 words, no year.' },
        summary_html: { type: 'string', description: 'One or two sentences in a single <p>, shown on the blog listing.' },
        tags: { type: 'array', items: { type: 'string', enum: ALLOWED_TAGS }, description: 'One to three tags from the allowed list, copied exactly.' },
        body_html: { type: 'string', description: 'The full post as HTML, with [[IMAGE_1]] and [[IMAGE_2]] markers.' },
        images: {
          type: 'object',
          properties: { featured: imageItem, inline_1: imageItem, inline_2: imageItem },
          required: ['featured', 'inline_1', 'inline_2'],
        },
        claims_to_verify: {
          type: 'array',
          description: 'Every figure, date, ranking or factual claim an editor should check before publishing, with the URL it came from.',
          items: { type: 'object', properties: { claim: { type: 'string' }, source_url: { type: 'string' } }, required: ['claim', 'source_url'] },
        },
        editor_notes: { type: 'string', description: 'Anything the editor should know: gaps in the research, brands left out for lack of a source, where a real farm or product photo would be better than a generated one. Empty string if nothing.' },
      },
      required: ['title', 'seo_title', 'meta_description', 'handle', 'summary_html', 'tags', 'body_html', 'images', 'claims_to_verify', 'editor_notes'],
    },
  } }],
  tool_choice: 'auto',
};

return [{ json: {
  request,
  researchOk: true,
  researchProblem,
  researchSources: [...sources.entries()].map(([url, title]) => ({ url, title })),
  allowedInternal: allowedInternal.map(l => l.url),
  allowedTags: ALLOWED_TAGS,
} }];

// Validates and cleans the AI article, styles tables for phones, and runs automatic checks
// whose results go in the review email. Nothing here publishes anything.
const cfg = $('Config').first().json;
const t = $('Pick Next Topic').first().json.topic;
const res = $input.first().json ?? {};

// Finds another node's output even when n8n has added a number to its name (for example
// "Build Writing Request2"), which happens when a node is pasted while an older copy is still on the canvas.
const fromNode = (base) => {
  for (const name of [base, base + '1', base + '2', base + '3', base + '4', base + '5']) {
    try { const j = $(name).first().json; if (j && Object.keys(j).length) return j; } catch (e) { /* not this one */ }
  }
  return null;
};
const wr = fromNode('Build Writing Request');
if (!wr?.allowedInternal) throw new Error('Parse Article could not read the output of "Build Writing Request". Check that the node exists, is connected before "AI: Write Article", and is named "Build Writing Request" (a number on the end is fine).');
const existingArticles = (fromNode('Check Shopify Setup') ?? fromNode('Build Research Request'))?.existingArticles ?? [];

// OpenRouter returns the article as the arguments of the submit_article tool call, as a JSON string.
const choice = res.choices?.[0];
const err = res.error ?? choice?.error;
if (err) throw new Error('AI error: ' + String(err.description ?? err.message ?? JSON.stringify(err)).slice(0, 500));
const cutOff = 'The article was cut off before it finished. Raise Config.maxTokens or lower Config.wordCount.';
if (choice?.finish_reason === 'length') throw new Error(cutOff);
const call = (choice?.message?.tool_calls ?? []).find(c => c?.function?.name === 'submit_article') ?? choice?.message?.tool_calls?.[0];
let raw = call?.function?.arguments ?? choice?.message?.content;
if (typeof raw === 'string') raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '');
let a;
try { a = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch (e) { throw new Error('The AI returned an article that is not valid JSON, usually because it was cut off. ' + cutOff); }
if (!a?.title || !a?.body_html) throw new Error('AI did not return an article. Response: ' + JSON.stringify(res).slice(0, 500));

const checks = [];
const base = String(cfg.storeUrl).replace(/\/+$/, '');
const host = (u) => ((String(u ?? '').match(/^https?:\/\/([^\/?#:]+)/i) || [])[1] || '').toLowerCase().replace(/^www\./, '');
const ownHost = host(base);
const norm = (u) => String(u).split('#')[0].split('?')[0].replace(/\/+$/, '');
const allowed = new Set(wr.allowedInternal.map(norm).concat([base]));
const researchHosts = new Set((wr.researchSources ?? []).map(s => host(s.url)).filter(Boolean));

// --- Strip anything that should never reach the storefront
const clean = (html) => String(html ?? '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<(script|style|iframe|object|embed|form)\b[\s\S]*?<\/\1>/gi, '')
  .replace(/<\/?(script|style|iframe|object|embed|form|input|img|link|meta|figure|figcaption|div|span)\b[^>]*>/gi, '')
  .replace(/\s(on\w+|style|class|id)\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, '')
  .replace(/<(\/?)h1\b[^>]*>/gi, '<$1h2>')
  .trim();

// --- Links: our own site only from the allowed list, no AI tools, no javascript
let removedLinks = [];
let offResearch = [];
const fixLinks = (html) => html.replace(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi, (m, attrs, text) => {
  const href = (attrs.match(/href\s*=\s*"([^"]*)"/i) || attrs.match(/href\s*=\s*'([^']*)'/i) || [])[1];
  if (!href || !/^https?:\/\//i.test(href)) { removedLinks.push(href || '(empty link)'); return text; }
  const h = host(href);
  if (/(^|\.)(claude\.ai|chatgpt\.com|openai\.com|anthropic\.com|gemini\.google\.com|perplexity\.ai)$/.test(h)) { removedLinks.push(href); return text; }
  if (h === ownHost) {
    if (!allowed.has(norm(href))) { removedLinks.push(href); return text; }
    return '<a href="' + href.replace(/"/g, '%22') + '">' + text + '</a>';
  }
  if (!researchHosts.has(h)) offResearch.push(href);
  return '<a href="' + href.replace(/"/g, '%22') + '" target="_blank" rel="noopener">' + text + '</a>';
});

// --- Tables that fit a phone screen (same styling as the grind and storage pages)
const styleTables = (html) => html
  .replace(/<table\b[^>]*>/gi, '<div style="overflow-x:auto;-webkit-overflow-scrolling:touch;margin:16px 0;"><table style="width:100%;border-collapse:collapse;table-layout:auto;font-size:clamp(12px,3.6vw,15px);margin:0;">')
  .replace(/<\/table>/gi, '</table></div>')
  .replace(/<th\b[^>]*>/gi, '<th style="background:#EDE4D3;text-align:left;padding:7px 6px;border:1px solid #d9cfbd;vertical-align:top;overflow-wrap:break-word;word-break:normal;">')
  .replace(/<td\b[^>]*>/gi, '<td style="padding:7px 6px;border:1px solid #e3dccf;vertical-align:top;overflow-wrap:break-word;word-break:normal;">');

const bodyClean = fixLinks(clean(a.body_html));
const summary = clean(a.summary_html).replace(/<a\b[^>]*>([\s\S]*?)<\/a>/gi, '$1');
const text = bodyClean.replace(/\[\[IMAGE_\d\]\]/g, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const words = text.split(' ').filter(Boolean).length;
const target = Number(cfg.wordCount) || 1500;
if (words < Math.max(400, target * 0.4)) throw new Error('The article is only ' + words + ' words, so it was not saved. Run the workflow again.');
const body = styleTables(bodyClean);

// --- Automatic checks (shown in the review email; none of them blocks the draft)
const count = (re) => (text.match(re) || []).length;
const flag = (re, label) => { const n = count(re); if (n) checks.push(label + ' (' + n + '×)'); };
flag(/\bAA\b/g, 'Mentions "AA". Fine if it explains the grade in general, not fine if it describes our coffee');
flag(/\borganic\b/gi, 'Uses the word "organic"');
flag(/\blab[- ]tested\b/gi, 'Says "lab-tested"');
flag(/\broasted to order\b/gi, 'Says "roasted to order"');
flag(/\b(certified|fair trade|award[- ]winning)\b/gi, 'Mentions a certification or award');
flag(/\b(co-?operatives?|partner farms?)\b/gi, 'Mentions cooperatives or partner farms');
flag(/\b(burns? fat|fat[- ]burning|boosts? (your )?metabolism|detox\w*|suppress\w* (your )?appetite)\b/gi, 'Fat-burning, metabolism, detox or appetite wording');
if (!t.health_sensitive) flag(/\b(lose weight|weight loss)\b/gi, 'Talks about weight loss on a topic that is not marked health-sensitive');
flag(/\b(cur(e|es|ing)|prevent(s|ing)?|treat(s|ing)?|(reduc|lower)(e|es|ing) (the|your) risk of|protect(s|ing)? against)\b[^.]{0,60}\b(disease|cancer|diabetes|alzheimer|parkinson|stroke|depression|heart|liver|dementia)/gi, 'Health-claim wording (cure, prevent, treat, lower the risk of an illness)');
flag(/\b(elevate|indulge|unleash|unlock|game-changer|delve|coffee lovers?)\b/gi, 'Off-brand marketing words');
if (count(/\$\s?\d/g) > count(/\$\s?55\b/g)) checks.push('States a price other than the $55 free-shipping threshold');
if (/!/.test(text)) checks.push('Contains an exclamation mark (fine only if it is part of a brand name)');
if (!/Short answer/i.test(text.slice(0, 200))) checks.push('Does not open with a "Short answer" paragraph');
if (!/<table/i.test(body)) checks.push('No table in the post');
if (!/Frequently asked questions/i.test(text)) checks.push('No FAQ section');
if (words < target * 0.7) checks.push('Short: ' + words + ' words against a target of ' + target);
if (removedLinks.length) checks.push('Removed ' + removedLinks.length + ' link(s) that were not on the allowed list: ' + removedLinks.slice(0, 5).join(', '));
if (offResearch.length) checks.push(offResearch.length + ' external link(s) point to sites that were not in the research: ' + [...new Set(offResearch)].slice(0, 5).join(', '));
const internalCount = (body.match(new RegExp('href="https?://(www\\.)?' + ownHost.replace(/\./g, '\\.'), 'gi')) || []).length;
if (internalCount < 2) checks.push('Only ' + internalCount + ' link(s) to your own site');
if (t.health_sensitive) checks.push('Health-sensitive topic: read every health statement against its source before publishing');
if (t.names_other_brands) checks.push('Names other brands: check each brand figure against its source before publishing');
if (!wr.researchOk) checks.push('RESEARCH WAS WEAK: ' + wr.researchProblem + ' Check every figure by hand');
else if (wr.researchProblem) checks.push(wr.researchProblem);

// --- Title, SEO fields, URL handle
const trimTo = (s, n) => { s = String(s ?? '').replace(/\s+/g, ' ').trim(); if (s.length <= n) return s; const cut = s.slice(0, n + 1); return cut.slice(0, cut.lastIndexOf(' ') > 20 ? cut.lastIndexOf(' ') : n).replace(/[\s,;:.\-]+$/, ''); };
const title = String(a.title).replace(/\s+/g, ' ').trim();
const seoTitle = trimTo(a.seo_title || title, 60);
const metaDescription = trimTo(a.meta_description, 158);
if (title.length > 70) checks.push('Title is ' + title.length + ' characters. Under 65 is better');

const slug = (s) => String(s ?? '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 70).replace(/-+$/g, '');
const taken = new Set(existingArticles.map(e => e.handle));
const baseSlug = slug(a.handle) || slug(title) || 'blog-post';
let handle = baseSlug;
for (let n = 2; taken.has(handle); n++) handle = baseSlug + '-' + n;

// Tags: only ones on the fixed list in Build Writing Request are kept, in that list's spelling.
const pickedTags = [...new Set((Array.isArray(a.tags) ? a.tags : []).map(x => String(x).trim()).filter(Boolean))];
const allowedTags = Array.isArray(wr.allowedTags) ? wr.allowedTags : [];
const tagKey = (x) => x.toLowerCase().replace(/&amp;/g, '&').replace(/\s+/g, ' ');
const tagByKey = new Map(allowedTags.map(x => [tagKey(x), x]));
const tags = allowedTags.length
  ? [...new Set(pickedTags.map(x => tagByKey.get(tagKey(x))).filter(Boolean))].slice(0, 3)
  : pickedTags.slice(0, 8);
if (allowedTags.length) {
  const dropped = pickedTags.filter(x => !tagByKey.has(tagKey(x)));
  if (dropped.length) checks.push('Dropped tag(s) that are not on your list: ' + dropped.join(', '));
  if (!tags.length) checks.push('The post has no tag, because none of the writer\'s tags were on your list. Add one by hand');
}

const img = a.images ?? {};
const one = (k) => ({ scene: String(img[k]?.scene ?? '').replace(/\s+/g, ' ').trim(), alt: trimTo(String(img[k]?.alt ?? '').replace(/"/g, ''), 125) });
const images = { featured: one('featured'), inline_1: one('inline_1'), inline_2: one('inline_2') };

return [{ json: {
  title, seoTitle, metaDescription, handle, summary, tags, body, words, images, checks,
  claimsToVerify: Array.isArray(a.claims_to_verify) ? a.claims_to_verify : [],
  editorNotes: String(a.editor_notes ?? '').trim(),
} }];

// One item per image. Each prompt = the fixed brand photo style (Config.imageStyle)
// + the scene the writer planned for that spot + framing notes.
const cfg = $('Config').first().json;
const art = $input.first().json;

const framing = {
  featured: 'FRAMING: landscape, 3:2. This is the header image for the article. One strong, simple subject that still reads at thumbnail size, with calm space toward the edges so it can be cropped to 16:9 or square.',
  inline: 'FRAMING: landscape, 3:2. This image sits inside the article next to the text it illustrates. Show the subject close enough to see its detail and texture.',
};
const slots = [
  { slot: 'featured', key: 'featured', suffix: 'featured', frame: framing.featured },
  { slot: 'inline_1', key: 'inline_1', suffix: '1', frame: framing.inline },
  { slot: 'inline_2', key: 'inline_2', suffix: '2', frame: framing.inline },
];

// OpenRouter's Image API (POST /api/v1/images) takes a model and a prompt, plus options that differ by model:
// OpenAI image models accept "quality"; Google's accept "resolution" (1K, 2K or 4K). Only the supported one is sent.
const model = String(cfg.imageModel || '');
const options = {};
if (/^openai\//i.test(model)) options.quality = /^(low|medium|high|xhigh|max|auto)$/i.test(String(cfg.imageQuality || '')) ? String(cfg.imageQuality).toLowerCase() : 'high';
if (/^google\//i.test(model)) options.resolution = /^(1K|2K|4K)$/i.test(String(cfg.imageSize || '')) ? String(cfg.imageSize).toUpperCase() : '1K';
const fallback = 'A cream ceramic cup of black coffee on a dark wood table beside a small pile of roasted coffee beans, seen from 45 degrees, with fine steam rising from the cup.';
return slots.map(s => {
  const scene = art.images[s.key]?.scene || fallback;
  const prompt = [
    String(cfg.imageStyle).trim(),
    '',
    'SCENE: ' + scene,
    '',
    s.frame,
    'No text or logos anywhere in the picture. All cups, bags, jars and equipment are plain and unbranded.',
  ].join('\n');
  return { json: {
    slot: s.slot,
    alt: art.images[s.key]?.alt || art.title,
    fileBase: art.handle + '-' + s.suffix, // the extension is added once the image format is known
    scene,
    request: { model, prompt, aspect_ratio: '16:9', n: 1, ...options },
  } };
});

// Sorts the image results into "made" and "failed". If none were made, the post is still
// saved, without images, and the review email says why.

// Finds another node's items even when n8n has added a number to its name (for example "Build Image Prompts1").
const itemsOf = (base) => {
  for (const name of [base, base + '1', base + '2', base + '3', base + '4', base + '5']) {
    try { const all = $(name).all(); if (all.length) return all; } catch (e) { /* not this one */ }
  }
  throw new Error('Could not find the output of "' + base + '". Check that the node exists and ran before this one.');
};
const reqs = itemsOf('Build Image Prompts');
const outs = $input.all();
const ext = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp' };
// The Image API returns { data: [{ b64_json, media_type }] }. If media_type is missing, read it from the first bytes.
const sniff = (b64) => b64.startsWith('/9j/') ? 'image/jpeg' : b64.startsWith('iVBOR') ? 'image/png' : b64.startsWith('UklGR') ? 'image/webp' : '';
const images = [];
const failed = [];
outs.forEach((it, i) => {
  const r = reqs[it.pairedItem?.item ?? i]?.json;
  if (!r) return;
  const d = it.json?.data?.[0];
  const b64 = typeof d?.b64_json === 'string' ? d.b64_json : '';
  const mime = String(d?.media_type || sniff(b64)).toLowerCase();
  if (b64.length > 1000 && ext[mime]) {
    images.push({ index: i, slot: r.slot, alt: r.alt, mime, filename: r.fileBase + '.' + ext[mime] });
  } else {
    const err = it.json?.error;
    failed.push({ slot: r.slot, reason: String(err?.description ?? err?.message ?? (b64 ? 'unsupported image format' : 'no image returned')).slice(0, 300) });
  }
});
for (const r of reqs) if (!images.some(x => x.slot === r.json.slot) && !failed.some(x => x.slot === r.json.slot)) failed.push({ slot: r.json.slot, reason: 'no result' });

const graphql = {
  query: 'mutation Stage($input: [StagedUploadInput!]!) { stagedUploadsCreate(input: $input) { stagedTargets { url resourceUrl parameters { name value } } userErrors { field message } } }',
  variables: { input: images.map(im => ({ filename: im.filename, mimeType: im.mime, resource: 'IMAGE', httpMethod: 'PUT' })) },
};
return [{ json: { count: images.length, images, failed, graphql } }];

// Builds the request that turns this week's blog post into a LinkedIn post.
// Runs after the blog draft is saved and its email is sent, so a problem here never affects the blog post.
// LinkedIn only lets outside tools publish posts (up to 3,000 characters), not long-form articles,
// so the piece is written to fit a post: about 400 words.

// Who it is written for, how long it is, and how much the model "thinks" first ('minimal', 'low', 'medium', 'high').
const AUDIENCE = 'professionals in the United States reading LinkedIn: people who drink coffee through the working day, and people who choose the coffee for an office, cafe or shop';
const WORDS = '350 to 450';
const REASONING = 'low';

// Finds another node's output even when n8n has added a number to its name (for example "Parse Article1").
const itemsOf = (base) => {
  for (const name of [base, base + '1', base + '2', base + '3', base + '4', base + '5']) {
    try { const all = $(name).all(); if (all.length) return all; } catch (e) { /* not this one */ }
  }
  return [];
};
const maybe = (base) => itemsOf(base)[0]?.json ?? null;
const need = (base) => {
  const j = maybe(base);
  if (!j) throw new Error('Could not find the output of "' + base + '". Check that the node exists, ran before this one, and is named "' + base + '" (a number on the end is fine).');
  return j;
};
const cfg = need('Config');
const t = need('Pick Next Topic').topic;
const art = need('Parse Article');

// --- Where the blog post will live once you publish it in Shopify
const base = String(cfg.storeUrl).replace(/\/+$/, '');
const handle = maybe('Shopify: Create Draft Post')?.data?.articleCreate?.article?.handle ?? art.handle;
const blogUrl = base + '/blogs/' + cfg.blogHandle + '/' + handle;

// --- The blog post as the model sees it: plain HTML, no styling, no image markers
const post = String(art.body)
  .replace(/<\/?div\b[^>]*>/gi, '')
  .replace(/\s(style|target|rel)="[^"]*"/gi, '')
  .replace(/(<p>\s*)?\[\[IMAGE_\d\]\](\s*<\/p>)?/gi, '')
  .replace(/\n{3,}/g, '\n\n').trim();

const system = [
  'You turn a Kirenge Gold blog post into a long LinkedIn post for ' + AUDIENCE + '.',
  'Write a new piece, not a summary and not a reworded copy. Pick the one idea in the post that is most useful or surprising to that reader, build the whole piece around it, and leave the rest to the blog. Do not reuse sentences from the post.',
  '',
  '=== BRAND FACTS: say nothing about Kirenge Gold beyond these ===',
  String(cfg.brandFacts).trim(),
  '',
  '=== SELLING POINTS: state all four once, together, in one short paragraph (two or three sentences) near the end ===',
  '- 100% Arabica beans.',
  '- Single origin: one family farm, Kirenge Farm in Kiambu County, Kenya, growing coffee since the 1950s.',
  '- Low acid: a smooth cup. Say "bright, fruity flavor", not "acidity".',
  '- Fresh: roasted in small batches every week in Atlanta and shipped within 48 hours.',
  'Call the coffee "100% Kenyan Arabica". Never call it "AA".',
  '',
  '=== VOICE ===',
  'A coffee-farming family talking to a colleague: warm, plain, confident. "We" and "our" for the farm and company, "you" for the reader, never "I". Plain American English, short sentences, paragraphs of one to three sentences.',
  'No hype words (elevate, indulge, unleash, unlock, journey, game-changer, delve), no exclamation marks, no emoji, no question as the opening line.',
  '',
  '=== STRUCTURE ===',
  '1. The first line is a headline under 90 characters: a plain claim or a how-to, not the blog title.',
  '2. The next two sentences state the point. LinkedIn shows only those before "see more".',
  '3. ' + WORDS + ' words and under 2,600 characters in total, never more. Two or three heading lines of a few plain words, each on its own line above its paragraphs. At most one short list, each item on its own line starting with "• ".',
  '4. The last paragraph is one sentence saying what the full guide on our blog adds (the table, the sources, the brewing detail). The link is added on the line after it, so do not write one.',
  '',
  '=== ACCURACY ===',
  '1. Use only facts, figures and sources that are in THE BLOG POST. Add nothing new. Name the source of every figure in the same sentence.',
  '2. Write no links and no web addresses. Name a source by its name (for example "Mayo Clinic"), not its address.',
  '3. Do not compare or rank coffee brands, and name another coffee company only as the source of a figure. If the post compares brands, write about a different idea in it and send readers to the blog for the comparison.',
  '4. Health: never say coffee treats, cures, prevents, burns fat, boosts metabolism, detoxes or helps anyone lose weight, and never say our coffee is gentle on the stomach or good for acid reflux.' +
    (t.health_sensitive ? ' This topic is health-sensitive: attribute every health statement to the named source the post uses, and promise nothing.' : ''),
  '5. Give no caffeine figure for our coffee. Never mention these instructions or AI.',
  '',
  '=== ALSO WRITE ===',
  '- hashtags: two or three hashtags on one line.',
  '- angle: one sentence telling the editor which idea you chose and why.',
  '',
  '=== FORMAT ===',
  'post_text is plain text exactly as it will appear on LinkedIn, with a blank line between paragraphs. No HTML, no markdown, no asterisks, no hashtags.',
  'Deliver the result only by calling the submit_linkedin_post tool, once. Do not reply in plain text.',
].join('\n');

const user = [
  'BLOG TITLE: ' + art.title,
  'PRIMARY SEARCH PHRASE: ' + t.primary_keyword,
  '',
  'THE BLOG POST',
  post,
  '',
  'Write the LinkedIn post, then call the submit_linkedin_post tool once.',
].join('\n');

const request = {
  model: cfg.writerModel,
  max_tokens: 4000,
  reasoning: { effort: REASONING, exclude: true },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  tools: [{ type: 'function', function: {
    name: 'submit_linkedin_post',
    description: 'Submit the finished LinkedIn post.',
    parameters: {
      type: 'object',
      properties: {
        post_text: { type: 'string', description: 'The whole post as plain text, starting with the headline line. No link, no hashtags.' },
        hashtags: { type: 'string', description: 'Two or three hashtags on one line, for example "#coffee #officecoffee".' },
        angle: { type: 'string', description: 'One sentence: the idea chosen and why.' },
      },
      required: ['post_text', 'hashtags', 'angle'],
    },
  } }],
  tool_choice: 'auto', 
};

return [{ json: { request, blogUrl, blogTitle: art.title } }];

// Prepares this week's LinkedIn post: the text the AI wrote, the blog link, and the featured image.
// "post: true" goes on to the LinkedIn node. "post: false" (with the reason) skips it. The review email reports either.
// The AI writes the post as plain text (see the prompt in "Build LinkedIn Request"), so nothing is reworded or checked here.

const MAX_CHARS = 3000; // LinkedIn's limit for a post

// Finds another node's items even when n8n has added a number to its name (for example "Collect Images1").
const itemsOf = (base) => {
  for (const name of [base, base + '1', base + '2', base + '3', base + '4', base + '5']) {
    try { const all = $(name).all(); if (all.length) return all; } catch (e) { /* not this one */ }
  }
  return [];
};

let text = '';
try {
  const cfg = itemsOf('Config')[0]?.json;
  const req = itemsOf('Build LinkedIn Request')[0]?.json;
  if (!cfg || !req?.blogUrl) throw new Error('Could not read "Config" or "Build LinkedIn Request". Check both nodes ran before this one.');

  // 1. The AI's reply: the post arrives as the arguments of a tool call
  const res = $input.first().json ?? {};
  const choice = res.choices?.[0];
  const err = res.error ?? choice?.error;
  if (err) throw new Error('The AI did not write the LinkedIn post: ' + String(err.description ?? err.message ?? JSON.stringify(err)).slice(0, 400));
  if (choice?.finish_reason === 'length') throw new Error('The LinkedIn post was cut off before it finished. Raise max_tokens in "Build LinkedIn Request".');
  let a;
  try { a = JSON.parse(choice.message.tool_calls[0].function.arguments); }
  catch (e) { throw new Error('The AI reply for the LinkedIn post could not be read.'); }
  if (!a.post_text) throw new Error('The AI reply has no "post_text". Paste the matching code into "Build LinkedIn Request" as well.');

  // 2. The link. The blog post is usually still hidden when this runs, and a link to a hidden post gives "page not found",
  //    so link to the post only if it is live; otherwise to the blog's front page, where it appears once published.
  let blogLive = false;
  try {
    const page = await this.helpers.httpRequest({ method: 'GET', url: req.blogUrl, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000 });
    blogLive = page.statusCode === 200;
  } catch (e) { /* treat as not live */ }
  const linkUrl = blogLive ? req.blogUrl : String(cfg.storeUrl).replace(/\/+$/, '') + '/blogs/' + cfg.blogHandle;

  // 3. The post: the AI's text, then the link, then the hashtags
  text = String(a.post_text).trim() + '\n' + linkUrl + '\n\n' + String(a.hashtags ?? '#coffee #kenyancoffee').trim();
  if (text.length > MAX_CHARS) throw new Error('The post is ' + text.length + ' characters and LinkedIn allows ' + MAX_CHARS + '. Lower WORDS at the top of "Build LinkedIn Request".');

  // 4. The image: this week's featured image (or the first one made), as a file the LinkedIn node can upload
  const notes = [];
  const out = { json: { post: true, text, mediaCategory: 'NONE', imageTitle: '', characters: text.length, blogLive, linkUrl, angle: String(a.angle ?? ''), notes } };
  const images = itemsOf('Collect Images')[0]?.json?.images ?? [];
  const im = images.find(x => x.slot === 'featured') ?? images[0];
  const b64 = im ? itemsOf('AI: Generate Image')[im.index]?.json?.data?.[0]?.b64_json : null;
  if (b64) {
    out.binary = { data: await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), im.filename, im.mime) };
    out.json.mediaCategory = 'IMAGE';
    out.json.imageTitle = String(im.alt ?? '').slice(0, 120);
  } else {
    notes.push('No image was available this week, so the post went out as text only');
  }
  return [out];

} catch (e) {
  // Nothing usable to post. The run carries on so the review email is still sent and can say why.
  return [{ json: { post: false, reason: String(e.message ?? e).replace(/ \[line \d+\]$/, ''), text, notes: [] } }];
}
